/* child vs descendant */
nav > a { font-weight: 600; }   /* sirf direct child */
nav a   { text-decoration: none; } /* kisi bhi depth par */

/* sibling */
h2 + p { margin-top: 0; }       /* h2 ke turant baad wala p */

/* grouping */
:is(h1, h2, h3) > a { color: inherit; }

/* attribute */
a[href^="https"]::after { content: " ↗"; }

p { color: black; }            /* (0,0,1) */
.note { color: blue; }         /* (0,1,0) wins over p */
#intro .note { color: green; } /* (1,1,0) wins */

/* same specificity -> baad wala jeetega */
.btn { background: gray; }
.btn { background: teal; }     /* teal */

/* low specificity default ke liye */
:where(.prose a) { color: blue; }

body { font-family: system-ui; color: #222; }

/* form controls inherit nahi karte */
button, input, select, textarea { font: inherit; color: inherit; }

/* links parent ka color le */
a { color: inherit; }

/* reset */
.card { all: unset; display: block; }

*, *::before, *::after { box-sizing: border-box; }

.card {
  width: 300px;      /* total 300px, padding aur border ke saath */
  padding: 16px;
  border: 2px solid #ddd;
  margin: 24px auto; /* margin box ke bahar */
}

span.badge {
  display: inline-block; /* ab width/height/padding vertical kaam karenge */
  padding: 4px 8px;
}

img { display: block; }   /* inline image ke neeche baseline gap hatata hai */

.hidden { display: none; }        /* layout se bhi hata */
.invisible { visibility: hidden; } /* jagah ghera rehta hai */

p { margin: 20px 0; }  /* do p ke beech 20px, 40px nahi */

/* child ka margin parent ke bahar leak hota hai */
.parent { background: #eee; }
.child  { margin-top: 40px; }

/* fixes */
.parent { padding-top: 1px; }      /* ya border */
.parent { display: flow-root; }    /* naya BFC, cleanest */
.parent { display: flex; }

:root {
  --brand: #0a84ff;
  --space: 8px;
}
@media (prefers-color-scheme: dark) {
  :root { --bg: #111; --fg: #eee; }
}
.btn {
  background: var(--brand);
  padding: calc(var(--space) * 2);
  color: var(--btn-fg, white); /* fallback */
}
.card.compact { --space: 4px; } /* local override */

/* JS: el.style.setProperty('--brand', 'tomato') */

.nav {
  display: flex;
  justify-content: space-between; /* main axis */
  align-items: center;            /* cross axis */
  gap: 12px;
  flex-wrap: wrap;
}

.column { display: flex; flex-direction: column; } /* axes swap ho gaye */

.layout { display: flex; gap: 16px; }
.sidebar { flex: 0 0 240px; }  /* fixed width, na grow na shrink */
.content { flex: 1; min-width: 0; } /* bacha hua space le */

/* equal columns */
.col { flex: 1; }

/* 2:1 ratio */
.a { flex: 2; } .b { flex: 1; }

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

/* fixed sidebar + fluid main */
.app { display: grid; grid-template-columns: 260px 1fr; }

.page {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-areas:
    "header header"
    "nav    main"
    "footer footer";
}
header { grid-area: header; }
nav    { grid-area: nav; }
main   { grid-area: main; }

@media (max-width: 700px) {
  .page { grid-template-areas: "header" "main" "nav" "footer"; grid-template-columns: 1fr; }
}

.card { position: relative; }          /* containing block banata hai */
.card .badge {
  position: absolute; top: 8px; right: 8px;
}

.header { position: sticky; top: 0; z-index: 10; } /* scroll par upar chipka */

.fab { position: fixed; right: 16px; bottom: 16px; }

.parent-a { position: relative; z-index: 1; }     /* context A */
.parent-b { position: relative; z-index: 2; }     /* context B, A ke upar */
.parent-a .modal { position: absolute; z-index: 9999; } /* phir bhi B ke neeche */

/* design system ke liye isolated layers */
.card { isolation: isolate; }

/* ek line, dono axis */
.center { display: grid; place-items: center; min-height: 100dvh; }

/* flex version */
.center { display: flex; justify-content: center; align-items: center; }

/* horizontal block */
.container { width: min(100% - 2rem, 960px); margin-inline: auto; }

/* absolute overlay */
.modal { position: absolute; inset: 0; margin: auto; width: 320px; height: fit-content; }

/* image ke around text wrap (asli use) */
img.avatar { float: left; margin: 0 1rem 1rem 0; shape-outside: circle(); }

/* parent ko float children ke baad contain karna */
.clearfix::after { content: ""; display: table; clear: both; } /* old */
.container { display: flow-root; }                              /* modern */

.card-wrap { container-type: inline-size; container-name: card; }

.card { display: grid; gap: 8px; }

@container card (min-width: 420px) {
  .card { grid-template-columns: 120px 1fr; }  /* wide hone par side-by-side */
}

.grid { display: grid; grid-template-columns: 1fr; gap: 16px; }

@media (min-width: 768px) {
  .grid { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 1100px) {
  .grid { grid-template-columns: repeat(3, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}
@media (hover: hover) { .btn:hover { background: #eee; } }

/* base: mobile */
.nav { display: flex; flex-direction: column; gap: 8px; }
.card { padding: 12px; }

/* tablet+ */
@media (min-width: 768px) {
  .nav { flex-direction: row; gap: 16px; }
  .card { padding: 20px; }
}

h1 { font-size: clamp(1.75rem, 1.2rem + 2.5vw, 3rem); }
p  { font-size: clamp(1rem, 0.95rem + 0.25vw, 1.125rem); }

.section { padding-block: clamp(2rem, 5vw, 5rem); }

.hero { min-height: 100vh; min-height: 100dvh; } /* fallback + modern */

.sheet { max-height: 80svh; }

.square { width: 50vmin; height: 50vmin; }

body {
  font: 1rem/1.5 system-ui, -apple-system, 'Segoe UI', sans-serif;
  -webkit-font-smoothing: antialiased;
}
h1, h2 { line-height: 1.2; text-wrap: balance; }
p { max-width: 65ch; text-wrap: pretty; }
code { font-family: ui-monospace, Menlo, monospace; }

.title {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.excerpt {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.row { display: flex; } .row .title { min-width: 0; flex: 1; }

button:hover { background: #eee; }
button:focus-visible { outline: 3px solid dodgerblue; outline-offset: 2px; }

li:not(:last-child) { border-bottom: 1px solid #ddd; }
tr:nth-child(even) { background: #fafafa; }

.card:has(img) { grid-template-columns: 120px 1fr; }
label:has(input:checked) { font-weight: 600; }

.btn { position: relative; }
.btn::after {
  content: "";
  position: absolute; inset: 0;
  border-radius: inherit;
  box-shadow: 0 0 0 0 rgba(0,128,255,.5);
  transition: box-shadow .2s;
}
.btn:hover::after { box-shadow: 0 0 0 6px rgba(0,128,255,.25); }

a[target="_blank"]::after { content: " ↗"; }
::selection { background: #ffe58a; }

.hero {
  background:
    linear-gradient(to bottom, rgb(0 0 0 / .5), transparent 60%),
    url(hero.jpg) center / cover no-repeat;
  min-height: 60vh;
}
.badge { background: conic-gradient(from 90deg, tomato, gold, tomato); }
.stripes { background: repeating-linear-gradient(45deg, #eee 0 10px, #fff 10px 20px); }

.card {
  border-radius: 12px;
  box-shadow:
    0 1px 2px rgb(0 0 0 / .08),
    0 8px 24px rgb(0 0 0 / .12);
}
.avatar { border-radius: 50%; }
.input { box-shadow: inset 0 1px 2px rgb(0 0 0 / .1); }
.logo { filter: drop-shadow(0 2px 4px rgb(0 0 0 / .3)); }
button:focus-visible { outline: 2px solid dodgerblue; outline-offset: 2px; }

.btn {
  transition: transform .15s ease-out, background-color .15s;
}
.btn:hover { transform: translateY(-2px); background-color: #0a6; }

/* accessibility */
@media (prefers-reduced-motion: reduce) {
  .btn { transition: none; }
}

@keyframes spin { to { transform: rotate(360deg); } }
.loader { animation: spin 1s linear infinite; }

@keyframes fade-up {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: none; }
}
.toast { animation: fade-up .3s ease-out both; }

.paused { animation-play-state: paused; }

.card { transition: transform .2s; }
.card:hover { transform: translateY(-4px) scale(1.02); }

.arrow { transform-origin: left center; transform: rotate(45deg); }

/* modern individual properties */
.icon { rotate: 45deg; scale: 1.2; translate: 0 -2px; }

/* slow: layout har frame */
.panel { transition: left .3s; }
.panel.open { left: 0; }

/* fast: compositor */
.panel { transform: translateX(-100%); transition: transform .3s; }
.panel.open { transform: none; }

/* hint sirf animation ke dauran */
.panel.animating { will-change: transform; }

/* layout trigger: expensive */
el.style.width = '300px';

/* paint only */
el.style.background = 'tomato';

/* composite only: cheapest */
el.style.transform = 'translateX(20px)';
el.style.opacity = '0.5';

// thrash: har iteration mein read + write
items.forEach((el) => {
  el.style.height = el.offsetWidth + 'px';
});

// batched
const widths = items.map((el) => el.offsetWidth); // saare reads
items.forEach((el, i) => { el.style.height = widths[i] + 'px'; }); // phir writes

requestAnimationFrame(() => { /* visual writes yahan */ });

