  font-family: 'Inter Fallback';
  src: local('Arial');
  size-adjust: 107%;
  ascent-override: 90%;
}
body { font-family: Inter, 'Inter Fallback', sans-serif; }

<link rel="preload" href="/fonts/inter.woff2" as="font" type="font/woff2" crossorigin>

.feed-item {
  content-visibility: auto;
  contain-intrinsic-size: auto 300px; /* estimate height */
}

.widget { contain: layout paint; } /* andar ka change bahar nahi jata */

/* Card.module.css */
.card { padding: 16px; }
.title { font-size: 1.25rem; }
.primary { composes: title; color: royalblue; }

// Card.tsx
import styles from './Card.module.css';
export const Card = ({ featured }) => (
  <div className={`${styles.card} ${featured ? styles.featured : ''}`}>...</div>
);

import styled from 'styled-components';

const Button = styled.button`
  padding: 8px 16px;
  background: ${(p) => (p.$primary ? 'royalblue' : 'white')};
  color: ${(p) => (p.$primary ? 'white' : 'inherit')};
  &:hover { filter: brightness(1.1); }
`;

<Button $primary>Save</Button>

:root {
  color-scheme: light dark;
  --blue-600: #2563eb;
  --color-bg: #fff; --color-fg: #111; --color-primary: var(--blue-600);
}
@media (prefers-color-scheme: dark) {
  :root { --color-bg: #0b0b0f; --color-fg: #eee; }
}
[data-theme="dark"] { --color-bg: #0b0b0f; --color-fg: #eee; } /* manual toggle */

body { background: var(--color-bg); color: var(--color-fg); }

@layer reset, base, components, utilities;

@layer reset { *, *::before, *::after { box-sizing: border-box; } }
@layer components {
  .card {
    padding: 16px;
    &:hover { box-shadow: 0 4px 12px rgb(0 0 0 / .15); }
    & .title { font-weight: 600; }
  }
}
@layer utilities { .p-0 { padding: 0; } } /* components ko hara dega */
